window.MOTION_SOURCES = {"source/Demos.tsx":"import {SimulatedBCamera} from './components/SimulatedBCamera';\nimport {OneToThreeBranch} from './components/OneToThreeBranch';\nimport React from 'react';\nimport {AbsoluteFill, Img, Easing, interpolate, staticFile, useCurrentFrame} from 'remotion';\nimport {Video} from '@remotion/media';\nimport {PatternedEditorialSplit} from './components/PatternedEditorialSplit';\nimport {HandDrawnFlowchart} from './components/HandDrawnFlowchart';\nimport {CaptionHighlight} from './components/CaptionHighlight';\nimport {CaptionGlitchRgb} from './components/CaptionGlitchRgb';\nimport {CameraPunch} from './components/CameraPunch';\nimport {FullFramePresenterBridge} from './components/FullFramePresenterBridge';\nimport {PresenterCardMorph} from './components/PresenterCardMorph';\nimport {EditorialSystemsDiagram} from './components/EditorialSystemsDiagram';\nimport {DualShowcase} from './components/DualShowcase';\nimport {PrimaryMediaShowcase} from './components/PrimaryMediaShowcase';\nimport {MinimalGradientBackground} from './components/MinimalGradientBackground';\n\nconst C={navy:'#004472',blue:'#0076BD',light:'#66A4D9',white:'#FFFFFF',gray:'#E6E7E8',ink:'#000000',yellow:'#F3DE89'};\nconst ease=(f:number,start:number,duration=22)=>interpolate(f,[start,start+duration],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp',easing:Easing.bezier(.16,1,.3,1)});\nconst phase=(f:number,start=12,end=154)=>Math.min(ease(f,start),1-ease(f,end,20));\nconst Heading=({children,style={}}:{children:React.ReactNode;style?:React.CSSProperties})=><div style={{fontSize:88,fontWeight:700,lineHeight:1.06,letterSpacing:-3,...style}}>{children}</div>;\nconst Kicker=({children}:{children:React.ReactNode})=><div style={{fontSize:25,letterSpacing:1,color:C.light,marginBottom:28}}>{children}</div>;\nexport const Presenter=()=> <Video src={staticFile('presenter.mp4')} muted objectFit='cover' style={{width:'100%',height:'100%'}} />;\nconst Stage=({children,light=false}:{children?:React.ReactNode;light?:boolean})=><AbsoluteFill style={{background:light?C.gray:C.navy,color:light?C.navy:C.white}}>{children}</AbsoluteFill>;\nconst Copy=({right=false,title='Make the idea clear.',detail='One visual. One useful message.'}:{right?:boolean;title?:string;detail?:string})=><div style={{position:'absolute',top:305,left:right?1060:120,width:720}}><Kicker>Perspective</Kicker><Heading>{title}</Heading><div style={{fontSize:34,lineHeight:1.4,marginTop:35,color:C.light}}>{detail}</div></div>;\n\nexport const TitleScene=()=>{const f=useCurrentFrame(),p=phase(f);return <><Presenter/><AbsoluteFill style={{opacity:p}}><Stage><div style={{position:'absolute',left:150,top:280,transform:`translateY(${(1-p)*45}px)`}}><Kicker>A better conversation</Kicker><Heading style={{fontSize:130}}>Sell the destination.</Heading><Heading style={{fontSize:130,color:C.light}}>Make the outcome real.</Heading><div style={{width:340*p,height:7,background:C.yellow,marginTop:50}}/></div></Stage></AbsoluteFill></>};\nexport const LowerThirdScene=()=>{const f=useCurrentFrame(),p=phase(f,25,145);return <><Presenter/><div style={{position:'absolute',left:100,bottom:100,opacity:p,transform:`translateX(${(1-p)*-110}px)`,borderLeft:`7px solid ${C.blue}`,background:'rgba(0,68,114,.94)',padding:'26px 45px',width:630}}><div style={{fontSize:55,fontWeight:700}}>Kevin Nuber</div><div style={{fontSize:28,marginTop:10,color:C.gray}}>A better conversation</div></div></>};\nexport const TrackerScene=()=>{const f=useCurrentFrame(),active=Math.min(2,Math.max(0,Math.floor((f-18)/45)));return <><Presenter/><div style={{position:'absolute',left:250,right:250,bottom:85,display:'flex',gap:8,opacity:phase(f)}}>{['Discover','Connect','Act'].map((t,i)=><div key={t} style={{flex:1,background:i===active?C.blue:C.navy,padding:'26px 32px',borderBottom:`5px solid ${i===active?C.yellow:'transparent'}`,fontSize:34}}><span style={{color:C.light,marginRight:22}}>0{i+1}</span>{t}</div>)}</div></>};\nexport const SplitScene=()=>{const f=useCurrentFrame(),p=ease(f,12,30);return <Stage><div style={{position:'absolute',left:1920-(1920-1040)*p,top:0,width:880,height:1080}}><Presenter/></div><div style={{opacity:p,transform:`translateX(${(1-p)*-100}px)`}}><Copy title='Lead with the outcome.' detail='Connect the conversation to what matters.'/></div></Stage>};\nexport const ProcessScene=()=>{const f=useCurrentFrame();return <Stage light><div style={{position:'absolute',left:120,top:130}}><Kicker>A clear sequence</Kicker><Heading>Give every step a purpose.</Heading></div><div style={{position:'absolute',left:120,right:120,top:405,display:'flex',gap:28}}>{['Listen first','Find the connection','Choose the next step'].map((t,i)=>{const p=ease(f,18+i*35);return <div key={t} style={{width:541,height:395,background:C.white,padding:45,boxSizing:'border-box',borderTop:`6px solid ${C.blue}`,opacity:p,transform:`translateY(${(1-p)*60}px)`}}><div style={{fontSize:60,color:C.blue,marginBottom:65}}>0{i+1}</div><div style={{fontSize:45,fontWeight:700,lineHeight:1.12}}>{t}</div></div>})}</div></Stage>};\nexport const ComparisonScene=()=>{const f=useCurrentFrame();return <Stage><div style={{position:'absolute',left:120,top:140}}><Kicker>A shift in perspective</Kicker><Heading>From features to meaning.</Heading></div>{['The product','The destination'].map((t,i)=><div key={t} style={{position:'absolute',left:120+i*930,top:390,width:750,height:410,padding:55,boxSizing:'border-box',background:i?C.blue:'rgba(255,255,255,.08)',border:'2px solid rgba(255,255,255,.25)',opacity:ease(f,18+i*45),transform:`translateY(${(1-ease(f,18+i*45))*35}px)`}}><div style={{fontSize:27,color:C.light,marginBottom:50}}>{i?'What it makes possible':'What it contains'}</div><Heading style={{fontSize:64}}>{t}</Heading><div style={{fontSize:33,marginTop:24}}>{i?'A clearer next chapter':'Details and specifications'}</div></div>)}<div style={{position:'absolute',left:904,top:542,fontSize:76,color:C.yellow,opacity:ease(f,55)}}>→</div></Stage>};\nexport const KeyMessageScene=()=>{const f=useCurrentFrame(),p=phase(f);return <Stage><div style={{position:'absolute',left:180,right:180,top:350,opacity:p,transform:`scale(${.97+.03*p})`}}><Kicker>The idea to remember</Kicker><Heading style={{fontSize:140}}>Clarity creates connection.</Heading><div style={{marginTop:45,height:7,width:interpolate(ease(f,32),[0,1],[0,820]),background:C.yellow}}/></div></Stage>};\nexport const ConceptScene=()=>{const f=useCurrentFrame();return <Stage light><div style={{position:'absolute',left:180,right:180,top:130,textAlign:'center',opacity:ease(f,6)}}><Kicker>The framework</Kicker><Heading>A meaningful conversation</Heading></div><svg viewBox='0 0 1920 1080' style={{position:'absolute',inset:0,width:'100%',height:'100%'}}>{[380,960,1540].map((x,i)=><path key={x} d={`M960 325 L960 420 L${x} 420 L${x} 545`} fill='none' stroke={C.blue} strokeWidth='3' pathLength={1} strokeDasharray={1} strokeDashoffset={1-ease(f,25+i*25)}/>)}</svg>{['Understand','Connect','Guide'].map((t,i)=><div key={t} style={{position:'absolute',left:140+i*580,top:545,width:480,height:250,background:C.white,boxSizing:'border-box',padding:42,opacity:ease(f,40+i*25),borderBottom:`5px solid ${C.blue}`}}><div style={{color:C.blue,fontSize:27,marginBottom:40}}>0{i+1}</div><Heading style={{fontSize:55}}>{t}</Heading></div>)}</Stage>};\n// Original vector landscape stands in for supplied B-roll, with deterministic parallax.\nconst Landscape=()=>{const f=useCurrentFrame();return <AbsoluteFill style={{background:C.gray,overflow:'hidden'}}><svg viewBox='0 0 1920 1080' preserveAspectRatio='xMidYMid slice' style={{width:'100%',height:'100%'}}><circle cx={1390-f*.45} cy='240' r='95' fill={C.yellow}/><path d={`M-200 850 L420 300 L900 880 L1320 410 L2100 930 V1100 H-200Z`} fill={C.light} transform={`translate(${-f*.2},0)`}/><path d='M-100 1000 L520 610 L1110 1000 L1670 580 L2100 980 V1200 H-100Z' fill={C.blue} transform={`translate(${-f*.5},0)`}/><path d='M-100 1050 Q700 760 2100 1010 V1200 H-100Z' fill={C.navy}/></svg><div style={{position:'absolute',left:130,top:120,color:C.navy}}><Kicker>Original motion illustration</Kicker><Heading>The destination.</Heading></div></AbsoluteFill>};\nexport const BrollScene=()=>{const f=useCurrentFrame(),p=Math.min(ease(f,25,18),1-ease(f,135,18));return <><Presenter/><div style={{position:'absolute',inset:0,opacity:p}}><Landscape/></div></>};\nexport const CtaScene=()=>{const f=useCurrentFrame();return <Stage><div style={{position:'absolute',left:180,top:280,width:1450,opacity:phase(f)}}><Kicker>Start the conversation</Kicker><Heading style={{fontSize:110}}>What does the next<br/>chapter look like?</Heading><div style={{display:'inline-block',marginTop:65,padding:'26px 42px',background:C.blue,fontSize:35,opacity:ease(f,55)}}>Explore the possibilities →</div></div></Stage>};\nexport const TransitionScene=()=>{const f=useCurrentFrame(),p=ease(f,48,30);return <><Presenter/><div style={{position:'absolute',inset:0,transform:`translateX(${(1-p)*1920}px)`,background:C.navy}}><div style={{position:'absolute',left:0,top:0,bottom:0,width:35,background:C.blue}}/><Copy title='A new perspective.' detail='A purposeful transition into the next idea.'/></div></>};\n// An original editorial board, visibly labeled as a sample—not a recreated product UI.\nconst SampleBoard=({variant=0}:{variant?:number})=><AbsoluteFill style={{background:C.white,color:C.navy,padding:'6%',boxSizing:'border-box'}}><div style={{fontSize:24,color:C.blue}}>Sample board · {variant?'Next chapter':'Conversation guide'}</div><div style={{fontSize:56,fontWeight:700,lineHeight:1.05,marginTop:35,letterSpacing:-2}}>{variant?'Make the outcome tangible.':'Start with what matters.'}</div><div style={{marginTop:38,height:'29%',background:C.gray,overflow:'hidden',position:'relative'}}><div style={{position:'absolute',width:'85%',height:'190%',borderRadius:'50%',border:`20px solid ${C.blue}`,left:'18%',top:'25%'}}/></div><div style={{display:'flex',gap:20,marginTop:35}}>{['Discover','Connect','Act'].map((t,i)=><div key={t} style={{flex:1,borderTop:`3px solid ${C.blue}`,paddingTop:18}}><div style={{fontSize:20,color:C.blue}}>0{i+1}</div><div style={{fontSize:26,marginTop:12}}>{t}</div></div>)}</div></AbsoluteFill>;\nconst Diagram=()=> <EditorialSystemsDiagram background={C.gray} kicker='A system that improves with every conversation' nodes={['Listen','Connect','Refine'].map((title,i)=>({id:String(i),title,detail:['Understand the need','Make the idea useful','Learn and adapt'][i],x:130+i*580,y:390,width:490,height:240,revealFrame:12+i*32,accent:i===1}))} connections={[{id:'a',path:'M620 510 L710 510',revealFrame:40},{id:'b',path:'M1200 510 L1290 510',revealFrame:72},{id:'c',path:'M1535 630 L1535 790 L375 790 L375 630',revealFrame:109,dashed:true}]} />;\nconst Flow=()=> <Stage><div style={{position:'absolute',left:130,top:120}}><Kicker>Build the relationship</Kicker><Heading>One idea leads to the next.</Heading></div><HandDrawnFlowchart panelColor={C.navy} nodes={['Listen','Connect','Act'].map((title,i)=>({id:String(i),title,number:`0${i+1}`,x:130+i*590,y:420,width:460,height:280,revealFrame:12+i*38}))} connectors={[{from:'0',to:'1',revealFrame:42},{from:'1',to:'2',revealFrame:80}]}/></Stage>;\nconst words='Make the outcome clear. Give the idea room.'.split(' ').map((text,i)=>({text,startMs:650+i*540,endMs:650+(i+1)*540,breakAfter:i===3}));\n\n\nconst BranchBucket=({color}:{color:string})=><svg viewBox=\"0 0 130 120\" width={110} height={100}><path d=\"M22 35 L34 105 Q65 115 96 105 L108 35 M22 35 Q65 48 108 35 M22 35 Q65 19 108 35 M38 29 Q38 3 65 3 Q92 3 92 29\" stroke={color} strokeWidth={4} strokeLinecap=\"round\" fill=\"none\"/><path d=\"M36 70 Q65 81 94 70 L89 98 Q65 105 41 98 Z\" fill={color} opacity={.12}/></svg>;\nexport const BranchDemo=()=> <OneToThreeBranch title=\"Three ways your money is taxed\" sourceLabel=\"Your money\" sourceMedia={<Img src={staticFile('reference/roth-money.png')} style={{width:'100%',height:'100%',objectFit:'contain'}}/>} sourceRevealFrame={8} branches={[\n {id:'taxable',label:'Taxable',revealFrame:40,icon:color=><BranchBucket color={color}/>},\n {id:'deferred',label:'Tax-deferred',revealFrame:75,icon:color=><BranchBucket color={color}/>},\n {id:'free',label:'Tax-free',revealFrame:110,icon:color=><BranchBucket color={color}/>,highlight:true},\n]} presenter={<Presenter/>}/>;\n\nexport const Demo=({id}:{id:string})=>{\n let content:React.ReactNode;\n switch(id){\n case 'simulated-b-camera':content=<SimulatedBCamera presenter={<Video src={staticFile('reference/bcamera-front.mp4')} muted objectFit='cover' style={{width:'100%',height:'100%'}}/>} cuts={[{id:'left-angle',from:32,durationInFrames:103,src:staticFile('reference/bcamera-generated.mp4'),trimBefore:32},{id:'right-angle',from:135,durationInFrames:30,src:staticFile('reference/bcamera-generated.mp4'),trimBefore:135}]}/>;break;\n case 'pip-one-to-three':content=<BranchDemo/>;break;\n case 'opening-title':content=<TitleScene/>;break;\n case 'presenter-lower-third':content=<LowerThirdScene/>;break;\n case 'stage-tracker':content=<TrackerScene/>;break;\n case 'clean-split':content=<SplitScene/>;break;\n case 'editorial-split':content=<PatternedEditorialSplit kicker='Three useful moves' headline='Make the conversation count.' video={<Presenter/>} items={['Discover','Connect','Act'].map((title,i)=>({number:`0${i+1}`,title,detail:['Start with the need.','Make the outcome real.','Choose one next step.'][i],revealFrame:25+i*38}))}/>;break;\n case 'process-cards':content=<ProcessScene/>;break;\n case 'sketch-flow':content=<Flow/>;break;\n case 'highlight-captions':content=<><Presenter/><CaptionHighlight words={words} accentColor={C.blue} accentShadowColor='rgba(0,118,189,.3)' bottom={95}/></>;break;\n case 'glitch-captions':content=<><Presenter/><CaptionGlitchRgb words={words} bottom={95}/></>;break;\n case 'comparison':content=<ComparisonScene/>;break;\n case 'key-message':content=<KeyMessageScene/>;break;\n case 'concept-scene':content=<ConceptScene/>;break;\n case 'broll-insert':content=<BrollScene/>;break;\n case 'closing-cta':content=<CtaScene/>;break;\n case 'panel-transition':content=<TransitionScene/>;break;\n case 'presenter-side-swap':content=<PresenterCardMorph video={<Presenter/>} preset='sideSwapBridge' startFrame={65} durationInFrames={32} fromScene={<Stage><Copy title='Start with the idea.'/></Stage>} toScene={<Stage><Copy right title='Then make it useful.'/></Stage>}/>;break;\n case 'corner-pip':case 'full-to-split':content=<FullFramePresenterBridge video={<Presenter/>} graphic={<Stage><div style={{position:'absolute',left:id==='corner-pip'?720:120,top:300,width:850}}><Kicker>Make room for the idea</Kicker><Heading>{id==='corner-pip'?'Let the graphic lead.':'Keep the conversation personal.'}</Heading><div style={{fontSize:34,color:C.light,marginTop:38}}>The presenter stays connected.</div></div></Stage>} sceneDurationInFrames={180} enterFrames={38} exitFrames={30} target={id==='corner-pip'?{x:85,y:690,width:510,height:287,borderRadius:22}:{x:1100,y:110,width:730,height:860,borderRadius:24}}/>;break;\n case 'pip-to-split':content=<PresenterCardMorph video={<Presenter/>} preset='pipToSplit' startFrame={50} durationInFrames={38} fromScene={<Stage><Copy right title='Let the idea lead.'/></Stage>} toScene={<Stage><Copy title='Bring the speaker back.'/></Stage>}/>;break;\n case 'systems-diagram':content=<Diagram/>;break;\n case 'dual-showcase':content=<DualShowcase presenter={<Presenter/>} backdropDim={0} left={{content:<SampleBoard/>,revealFrame:20}} right={{content:<SampleBoard variant={1}/>,revealFrame:65}}/>;break;\n case 'primary-media':case 'media-only':case 'circle-pip':content=<PrimaryMediaShowcase media={<SampleBoard/>} presenter={id==='media-only'?undefined:<Presenter/>} presenterShape={id==='circle-pip'?'circle':'rounded'} presenterPosition='bottom-left' presenterRect={id==='primary-media'?{width:420,height:237,borderRadius:20}:undefined} mediaRevealFrame={8} presenterRevealFrame={38}/>;break;\n case 'gradient-full':case 'gradient-card':content=<MinimalGradientBackground scheme='dark' barMode={id==='gradient-card'?'card':'fullBleed'} stageDarkColor={C.gray} baseDarkColor={C.navy} animationIn={false} animationOut={false}><div style={{position:'absolute',left:'16%',right:'16%',top:'36%'}}><Kicker>A quiet backdrop</Kicker><Heading style={{fontSize:100}}>Space for the idea.</Heading></div></MinimalGradientBackground>;break;\n case 'camera-punch':content=<CameraPunch cues={[{startFrame:35,endFrame:145,scale:1.12,transitionFrames:22,focusX:49,focusY:32}]}><Presenter/></CameraPunch>;break;\n default:throw new Error(`Unknown demo: ${id}`);\n }\n return <AbsoluteFill style={{background:C.navy,color:C.white,fontFamily:'Library Arial, Arial, sans-serif',overflow:'hidden'}}><style>{`@font-face{font-family:'Library Arial';src:url('${staticFile('fonts/Arial-Regular.ttf')}')}@font-face{font-family:'Library Arial';src:url('${staticFile('fonts/Arial-Bold.ttf')}');font-weight:700}`}</style>{content}</AbsoluteFill>;\n};\n","source/components/PatternedEditorialSplit.tsx":"import type { ReactNode } from \"react\";\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  spring,\n  useCurrentFrame,\n  useVideoConfig,\n} from \"remotion\";\n\nconst COLORS = {\n  blue: \"#0076BD\",\n  darkBlue: \"#004472\",\n  lightBlue: \"#66A4D9\",\n  white: \"#FFFFFF\",\n} as const;\n\nconst FONT_FAMILY = '\"Arial Nova\", Arial, Helvetica, sans-serif';\n\nexport type EditorialSplitItem = {\n  number: string;\n  title: string;\n  detail: string;\n  revealFrame: number;\n};\n\nexport type PatternedEditorialSplitProps = {\n  kicker: string;\n  headline: string;\n  items: EditorialSplitItem[];\n  video: ReactNode;\n  presenterLabel?: string;\n  videoSide?: \"left\" | \"right\";\n};\n\nconst reveal = (frame: number, start: number, duration = 18) =>\n  interpolate(frame, [start, start + duration], [0, 1], {\n    extrapolateLeft: \"clamp\",\n    extrapolateRight: \"clamp\",\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n  });\n\nexport const PatternedEditorialSplit = ({\n  kicker,\n  headline,\n  items,\n  video,\n  presenterLabel,\n  videoSide = \"right\",\n}: PatternedEditorialSplitProps) => {\n  const frame = useCurrentFrame();\n  const { fps, durationInFrames } = useVideoConfig();\n  const entrance = spring({\n    frame,\n    fps,\n    durationInFrames: 28,\n    config: { damping: 20, stiffness: 125, mass: 0.9 },\n  });\n  const exit = interpolate(\n    frame,\n    [durationInFrames - 16, durationInFrames],\n    [1, 0],\n    {\n      extrapolateLeft: \"clamp\",\n      extrapolateRight: \"clamp\",\n      easing: Easing.bezier(0.7, 0, 0.84, 0),\n    },\n  );\n  const activeIndex = items.reduce(\n    (latest, item, index) => (frame >= item.revealFrame ? index : latest),\n    -1,\n  );\n  const videoOnRight = videoSide === \"right\";\n\n  return (\n    <AbsoluteFill\n      style={{\n        overflow: \"hidden\",\n        background: COLORS.darkBlue,\n        color: COLORS.white,\n        fontFamily: FONT_FAMILY,\n        opacity: exit,\n      }}\n    >\n      <AbsoluteFill\n        style={{\n          backgroundImage: [\n            \"radial-gradient(circle, rgba(255,255,255,0.2) 1.5px, transparent 1.8px)\",\n            \"linear-gradient(rgba(102,164,217,0.2) 1px, transparent 1px)\",\n            \"linear-gradient(90deg, rgba(102,164,217,0.2) 1px, transparent 1px)\",\n            \"linear-gradient(rgba(102,164,217,0.12) 2px, transparent 2px)\",\n            \"linear-gradient(90deg, rgba(102,164,217,0.12) 2px, transparent 2px)\",\n            \"radial-gradient(circle at 18% 15%, rgba(0,118,189,0.24), transparent 33%)\",\n          ].join(\",\"),\n          backgroundSize:\n            \"84px 84px, 84px 84px, 84px 84px, 336px 336px, 336px 336px, 100% 100%\",\n          backgroundPosition: `${-frame * 0.08}px ${-frame * 0.05}px`,\n        }}\n      />\n\n      <div\n        style={{\n          position: \"absolute\",\n          inset: 58,\n          border: \"1px solid rgba(102,164,217,0.24)\",\n          borderRadius: 36,\n        }}\n      />\n\n      <div\n        style={{\n          position: \"absolute\",\n          left: videoOnRight ? 112 : 1018,\n          top: 88,\n          width: 790,\n          height: 904,\n          display: \"flex\",\n          flexDirection: \"column\",\n          justifyContent: \"center\",\n          opacity: entrance,\n          transform: `translateX(${(1 - entrance) * (videoOnRight ? -54 : 54)}px)`,\n        }}\n      >\n        <div\n          style={{\n            color: COLORS.lightBlue,\n            fontSize: 25,\n            fontWeight: 700,\n            letterSpacing: 0.8,\n          }}\n        >\n          {kicker}\n        </div>\n        <div\n          style={{\n            width: 735,\n            marginTop: 24,\n            fontSize: 56,\n            lineHeight: 1.04,\n            fontWeight: 700,\n            letterSpacing: -2.4,\n          }}\n        >\n          {headline}\n        </div>\n\n        <div\n          style={{\n            display: \"grid\",\n            gap: 16,\n            marginTop: 46,\n          }}\n        >\n          {items.map((item, index) => {\n            const progress = reveal(frame, item.revealFrame);\n            const isActive = index === activeIndex;\n\n            return (\n              <div\n                key={`${item.number}-${item.title}`}\n                style={{\n                  display: \"grid\",\n                  gridTemplateColumns: \"64px 1fr\",\n                  gap: 20,\n                  alignItems: \"center\",\n                  minHeight: 124,\n                  padding: \"20px 24px\",\n                  border: `2px solid ${\n                    isActive\n                      ? \"rgba(102,164,217,0.95)\"\n                      : \"rgba(255,255,255,0.16)\"\n                  }`,\n                  borderRadius: 22,\n                  background: isActive\n                    ? \"rgba(0,118,189,0.3)\"\n                    : \"rgba(0,42,72,0.42)\",\n                  opacity: progress * (isActive ? 1 : 0.78),\n                  transform: `translateX(${(1 - progress) * -32}px)`,\n                }}\n              >\n                <div\n                  style={{\n                    display: \"grid\",\n                    placeItems: \"center\",\n                    width: 60,\n                    height: 60,\n                    borderRadius: 17,\n                    background: isActive\n                      ? COLORS.blue\n                      : \"rgba(255,255,255,0.1)\",\n                    fontSize: 23,\n                    fontWeight: 700,\n                  }}\n                >\n                  {item.number}\n                </div>\n                <div>\n                  <div\n                    style={{\n                      fontSize: 31,\n                      lineHeight: 1.08,\n                      fontWeight: 700,\n                      letterSpacing: -0.7,\n                    }}\n                  >\n                    {item.title}\n                  </div>\n                  <div\n                    style={{\n                      marginTop: 8,\n                      color: \"rgba(255,255,255,0.7)\",\n                      fontSize: 20,\n                      lineHeight: 1.24,\n                    }}\n                  >\n                    {item.detail}\n                  </div>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </div>\n\n      <div\n        style={{\n          position: \"absolute\",\n          left: videoOnRight ? 1018 : 112,\n          top: 104,\n          width: 750,\n          height: 872,\n          borderRadius: 38,\n          overflow: \"hidden\",\n          background: \"#111111\",\n          border: \"2px solid rgba(102,164,217,0.55)\",\n          boxShadow: \"0 34px 90px rgba(0,20,36,0.5)\",\n          opacity: entrance,\n          transform: `translateX(${\n            (1 - entrance) * (videoOnRight ? 120 : -120)\n          }px) scale(${0.96 + entrance * 0.04})`,\n        }}\n      >\n        {video}\n        <AbsoluteFill\n          style={{\n            pointerEvents: \"none\",\n            boxShadow: \"inset 0 0 90px rgba(0,0,0,0.18)\",\n          }}\n        />\n        {presenterLabel ? (\n          <div\n            style={{\n              position: \"absolute\",\n              left: 30,\n              bottom: 28,\n              padding: \"13px 18px\",\n              borderRadius: 14,\n              background: \"rgba(0,68,114,0.86)\",\n              border: \"1px solid rgba(255,255,255,0.22)\",\n              fontSize: 20,\n              fontWeight: 700,\n            }}\n          >\n            {presenterLabel}\n          </div>\n        ) : null}\n      </div>\n    </AbsoluteFill>\n  );\n};\n","source/components/HandDrawnFlowchart.tsx":"import {Easing, interpolate, useCurrentFrame} from \"remotion\";\n\nconst DEFAULT_COLORS = {\n  ink: \"#FFFFFF\",\n  accent: \"#F3DE89\",\n  panel: \"#001E33\",\n} as const;\n\nconst DEFAULT_FONT = '\"Arial Nova\", Arial, Helvetica, sans-serif';\n\nexport type HandDrawnFlowchartNode = {\n  id: string;\n  title: string;\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  revealFrame: number;\n  number?: string;\n  eyebrow?: string;\n  detail?: string;\n  textScale?: number;\n};\n\nexport type HandDrawnFlowchartConnector = {\n  from: string;\n  to: string;\n  revealFrame: number;\n};\n\nexport type HandDrawnFlowchartProps = {\n  nodes: HandDrawnFlowchartNode[];\n  connectors: HandDrawnFlowchartConnector[];\n  canvasWidth?: number;\n  canvasHeight?: number;\n  inkColor?: string;\n  accentColor?: string;\n  panelColor?: string;\n  fontFamily?: string;\n  drawFrames?: number;\n  highlightLatest?: boolean;\n};\n\nconst progressAt = (frame: number, start: number, duration: number) =>\n  interpolate(frame, [start, start + duration], [0, 1], {\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n    extrapolateLeft: \"clamp\",\n    extrapolateRight: \"clamp\",\n  });\n\nconst roughRectanglePath = (width: number, height: number, variant: 0 | 1) => {\n  const inset = variant === 0 ? 9 : 13;\n  const drift = variant === 0 ? 0 : 4;\n\n  return [\n    `M ${inset + 20} ${inset + drift}`,\n    `C ${Math.round(width * 0.28)} ${inset - 3}, ${Math.round(width * 0.7)} ${inset + 3}, ${width - inset - 20} ${inset + 1}`,\n    `Q ${width - inset + 4} ${inset + 1}, ${width - inset + 1} ${inset + 22}`,\n    `C ${width - inset - 2} ${Math.round(height * 0.35)}, ${width - inset + 2} ${Math.round(height * 0.72)}, ${width - inset - 2} ${height - inset - 20}`,\n    `Q ${width - inset - 3} ${height - inset + 2}, ${width - inset - 24} ${height - inset}`,\n    `C ${Math.round(width * 0.7)} ${height - inset + 3}, ${Math.round(width * 0.3)} ${height - inset - 3}, ${inset + 22} ${height - inset + 1}`,\n    `Q ${inset - 2} ${height - inset - 1}, ${inset + 1} ${height - inset - 23}`,\n    `C ${inset + 4} ${Math.round(height * 0.68)}, ${inset - 3} ${Math.round(height * 0.35)}, ${inset + 2} ${inset + 20}`,\n    `Q ${inset + 3} ${inset + 1}, ${inset + 20} ${inset + drift}`,\n    \"Z\",\n  ].join(\" \");\n};\n\nconst SketchNode = ({\n  node,\n  index,\n  isCurrent,\n  inkColor,\n  accentColor,\n  panelColor,\n  drawFrames,\n}: {\n  node: HandDrawnFlowchartNode;\n  index: number;\n  isCurrent: boolean;\n  inkColor: string;\n  accentColor: string;\n  panelColor: string;\n  drawFrames: number;\n}) => {\n  const frame = useCurrentFrame();\n  const draw = progressAt(frame, node.revealFrame, drawFrames);\n  const copy = progressAt(\n    frame,\n    node.revealFrame + Math.round(drawFrames * 0.55),\n    12,\n  );\n  const current = isCurrent\n    ? progressAt(frame, node.revealFrame + drawFrames, 10)\n    : 0;\n  const settle = interpolate(current, [0, 1], [1, 1.018]);\n  const textScale = node.textScale ?? 1;\n\n  return (\n    <div\n      style={{\n        position: \"absolute\",\n        left: node.x,\n        top: node.y,\n        width: node.width,\n        height: node.height,\n        transform: `scale(${settle}) rotate(${index % 2 === 0 ? -0.35 : 0.3}deg)`,\n        transformOrigin: \"center\",\n      }}\n    >\n      <svg\n        viewBox={`0 0 ${node.width} ${node.height}`}\n        width={node.width}\n        height={node.height}\n        style={{\n          position: \"absolute\",\n          inset: 0,\n          overflow: \"visible\",\n          opacity: Math.min(1, draw * 10),\n        }}\n      >\n        <path\n          d={roughRectanglePath(node.width, node.height, 0)}\n          pathLength={1}\n          fill={panelColor}\n          fillOpacity={0.72 + current * 0.18}\n          stroke={accentColor}\n          strokeOpacity={0.22 + current * 0.26}\n          strokeWidth={13}\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n          strokeDasharray={1}\n          strokeDashoffset={1 - draw}\n        />\n        <path\n          d={roughRectanglePath(node.width, node.height, 1)}\n          pathLength={1}\n          fill=\"none\"\n          stroke={inkColor}\n          strokeOpacity={0.42 + current * 0.58}\n          strokeWidth={4}\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n          strokeDasharray={1}\n          strokeDashoffset={1 - draw}\n        />\n      </svg>\n\n      <div\n        style={{\n          position: \"absolute\",\n          inset: \"30px 34px 26px\",\n          color: inkColor,\n          opacity: copy,\n          transform: `translateY(${(1 - copy) * 14}px)`,\n        }}\n      >\n        <div style={{display: \"flex\", alignItems: \"center\", gap: 13}}>\n          <div\n            style={{\n              width: 42 * textScale,\n              height: 42 * textScale,\n              flex: \"0 0 auto\",\n              borderRadius: \"50%\",\n              display: \"grid\",\n              placeItems: \"center\",\n              background: current > 0.5 ? accentColor : `${accentColor}24`,\n              border: `2px solid ${accentColor}`,\n              color: current > 0.5 ? panelColor : accentColor,\n              fontSize: 17 * textScale,\n              fontWeight: 900,\n            }}\n          >\n            {node.number ?? String(index + 1).padStart(2, \"0\")}\n          </div>\n          {node.eyebrow ? (\n            <div\n              style={{\n                fontSize: 17 * textScale,\n                fontWeight: 800,\n                letterSpacing: 1.4,\n                color: accentColor,\n              }}\n            >\n              {node.eyebrow}\n            </div>\n          ) : null}\n        </div>\n        <div\n          style={{\n            fontSize: 35 * textScale,\n            lineHeight: 1.02,\n            fontWeight: 900,\n            marginTop: 14,\n          }}\n        >\n          {node.title}\n        </div>\n        {node.detail ? (\n          <div\n            style={{\n              fontSize: 18 * textScale,\n              lineHeight: 1.25,\n              color: \"rgba(255,255,255,.65)\",\n              marginTop: 8,\n            }}\n          >\n            {node.detail}\n          </div>\n        ) : null}\n      </div>\n    </div>\n  );\n};\n\nconst SketchConnector = ({\n  connector,\n  nodes,\n  inkColor,\n  accentColor,\n  drawFrames,\n  canvasWidth,\n  canvasHeight,\n}: {\n  connector: HandDrawnFlowchartConnector;\n  nodes: HandDrawnFlowchartNode[];\n  inkColor: string;\n  accentColor: string;\n  drawFrames: number;\n  canvasWidth: number;\n  canvasHeight: number;\n}) => {\n  const frame = useCurrentFrame();\n  const from = nodes.find((node) => node.id === connector.from);\n  const to = nodes.find((node) => node.id === connector.to);\n\n  if (!from || !to) return null;\n\n  const draw = progressAt(frame, connector.revealFrame, drawFrames);\n  const arrow = progressAt(\n    frame,\n    connector.revealFrame + Math.round(drawFrames * 0.68),\n    7,\n  );\n  const x1 = from.x + from.width - 3;\n  const y1 = from.y + from.height / 2;\n  const x2 = to.x + 3;\n  const y2 = to.y + to.height / 2;\n  const span = x2 - x1;\n  const path = `M ${x1} ${y1} C ${x1 + span * 0.32} ${y1 - 8}, ${x1 + span * 0.66} ${y2 + 10}, ${x2} ${y2}`;\n\n  return (\n    <svg\n      width={canvasWidth}\n      height={canvasHeight}\n      viewBox={`0 0 ${canvasWidth} ${canvasHeight}`}\n      style={{\n        position: \"absolute\",\n        inset: 0,\n        opacity: Math.min(1, draw * 10),\n      }}\n    >\n      <path\n        d={path}\n        pathLength={1}\n        fill=\"none\"\n        stroke={inkColor}\n        strokeOpacity={0.2}\n        strokeWidth={10}\n        strokeLinecap=\"round\"\n        strokeDasharray={1}\n        strokeDashoffset={1 - draw}\n      />\n      <path\n        d={path}\n        pathLength={1}\n        fill=\"none\"\n        stroke={accentColor}\n        strokeWidth={4}\n        strokeLinecap=\"round\"\n        strokeDasharray={1}\n        strokeDashoffset={1 - draw}\n      />\n      <path\n        d={`M ${x2 - 17} ${y2 - 13} L ${x2} ${y2} L ${x2 - 20} ${y2 + 12}`}\n        fill=\"none\"\n        stroke={accentColor}\n        strokeWidth={4}\n        strokeLinecap=\"round\"\n        strokeLinejoin=\"round\"\n        opacity={arrow}\n      />\n    </svg>\n  );\n};\n\nexport const HandDrawnFlowchart = ({\n  nodes,\n  connectors,\n  canvasWidth = 1920,\n  canvasHeight = 1080,\n  inkColor = DEFAULT_COLORS.ink,\n  accentColor = DEFAULT_COLORS.accent,\n  panelColor = DEFAULT_COLORS.panel,\n  fontFamily = DEFAULT_FONT,\n  drawFrames = 18,\n  highlightLatest = true,\n}: HandDrawnFlowchartProps) => {\n  const frame = useCurrentFrame();\n  const visibleNodes = nodes.filter((node) => frame >= node.revealFrame);\n  const currentId = highlightLatest\n    ? visibleNodes[visibleNodes.length - 1]?.id\n    : undefined;\n\n  return (\n    <div style={{position: \"absolute\", inset: 0, fontFamily}}>\n      {connectors.map((connector, index) => (\n        <SketchConnector\n          key={`${connector.from}-${connector.to}-${index}`}\n          connector={connector}\n          nodes={nodes}\n          inkColor={inkColor}\n          accentColor={accentColor}\n          drawFrames={drawFrames}\n          canvasWidth={canvasWidth}\n          canvasHeight={canvasHeight}\n        />\n      ))}\n      {nodes.map((node, index) => (\n        <SketchNode\n          key={node.id}\n          node={node}\n          index={index}\n          isCurrent={node.id === currentId}\n          inkColor={inkColor}\n          accentColor={accentColor}\n          panelColor={panelColor}\n          drawFrames={drawFrames}\n        />\n      ))}\n    </div>\n  );\n};\n","source/components/CaptionHighlight.tsx":"import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from \"remotion\";\nimport {groupCaptionWords, type CaptionWord} from \"./CaptionWords\";\n\nconst DEFAULT_FONT = '\"Arial Nova\", Arial, Helvetica, sans-serif';\n\nexport type CaptionHighlightProps = {\n  words: CaptionWord[];\n  accentColor?: string;\n  accentShadowColor?: string;\n  textColor?: string;\n  textShadowColor?: string;\n  fontFamily?: string;\n  fontSize?: number;\n  bottom?: number;\n  maxWordsPerGroup?: number;\n  pauseThresholdMs?: number;\n};\n\nconst clamp = {\n  extrapolateLeft: \"clamp\" as const,\n  extrapolateRight: \"clamp\" as const,\n};\n\nexport const CaptionHighlight = ({\n  words,\n  accentColor = \"#EE6350\",\n  accentShadowColor = \"rgba(238,99,80,.27)\",\n  textColor = \"#FFFFFF\",\n  textShadowColor = \"rgba(0,0,0,.55)\",\n  fontFamily = DEFAULT_FONT,\n  fontSize = 80,\n  bottom = 135,\n  maxWordsPerGroup = 4,\n  pauseThresholdMs = 150,\n}: CaptionHighlightProps) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n  const nowMs = (frame / fps) * 1000;\n  const groups = groupCaptionWords(words, maxWordsPerGroup, pauseThresholdMs);\n  const group = groups.find(\n    (candidate) => nowMs >= candidate.startMs && nowMs < candidate.endMs,\n  );\n\n  if (!group) return null;\n\n  const groupIn = interpolate(\n    nowMs,\n    [group.startMs, group.startMs + 120],\n    [0, 1],\n    {...clamp, easing: Easing.out(Easing.cubic)},\n  );\n  const groupOut = interpolate(\n    nowMs,\n    [group.endMs - 100, group.endMs],\n    [1, 0],\n    {...clamp, easing: Easing.in(Easing.cubic)},\n  );\n  const groupOpacity = Math.min(groupIn, groupOut);\n\n  return (\n    <AbsoluteFill style={{pointerEvents: \"none\"}}>\n      <div\n        style={{\n          position: \"absolute\",\n          left: 0,\n          right: 0,\n          bottom,\n          display: \"flex\",\n          flexWrap: \"wrap\",\n          justifyContent: \"center\",\n          alignItems: \"flex-end\",\n          gap: 8,\n          padding: \"0 100px\",\n          opacity: groupOpacity,\n          transform: `translateY(${(1 - groupIn) * 12}px)`,\n          fontFamily,\n        }}\n      >\n        {group.words.map((word) => {\n          const sweepIn = interpolate(\n            nowMs,\n            [word.startMs, word.startMs + 150],\n            [0, 1],\n            {...clamp, easing: Easing.out(Easing.cubic)},\n          );\n          const sweepOut = interpolate(\n            nowMs,\n            [word.endMs, word.endMs + 100],\n            [1, 0],\n            {...clamp, easing: Easing.in(Easing.cubic)},\n          );\n          const highlight = Math.min(sweepIn, sweepOut);\n\n          return (\n            <span\n              key={`${word.startMs}-${word.text}`}\n              style={{\n                position: \"relative\",\n                display: \"inline-block\",\n                padding: \"7px 12px 9px\",\n                color: textColor,\n                fontSize,\n                fontWeight: 900,\n                letterSpacing: -1.2,\n                lineHeight: 1,\n                textShadow: `0 6px 18px ${textShadowColor}`,\n                transform: `scale(${1 + highlight * 0.025})`,\n                transformOrigin: \"50% 60%\",\n              }}\n            >\n              <span\n                style={{\n                  position: \"absolute\",\n                  inset: 0,\n                  zIndex: -1,\n                  borderRadius: 10,\n                  background: accentColor,\n                  boxShadow: `0 12px 30px ${accentShadowColor}`,\n                  opacity: highlight,\n                  transform: `scaleX(${highlight})`,\n                  transformOrigin: \"left center\",\n                }}\n              />\n              {word.text}\n            </span>\n          );\n        })}\n      </div>\n    </AbsoluteFill>\n  );\n};\n","source/components/CaptionGlitchRgb.tsx":"import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from \"remotion\";\nimport {groupCaptionWords, type CaptionWord} from \"./CaptionWords\";\n\nconst DEFAULT_FONT = '\"Arial Nova\", Arial, Helvetica, sans-serif';\n\nexport type CaptionGlitchRgbProps = {\n  words: CaptionWord[];\n  fringeAColor?: string;\n  fringeBColor?: string;\n  textColor?: string;\n  textShadowColor?: string;\n  vignetteColor?: string;\n  scanlineColor?: string;\n  fontFamily?: string;\n  fontSize?: number;\n  bottom?: number;\n  maxWordsPerGroup?: number;\n  pauseThresholdMs?: number;\n  showScanlines?: boolean;\n};\n\nconst clamp = {\n  extrapolateLeft: \"clamp\" as const,\n  extrapolateRight: \"clamp\" as const,\n};\n\nconst deterministicTravel = (index: number) => 8 + ((index * 7 + 5) % 7);\n\nexport const CaptionGlitchRgb = ({\n  words,\n  fringeAColor = \"#EE6350\",\n  fringeBColor = \"#66A4D9\",\n  textColor = \"#FFFFFF\",\n  textShadowColor = \"rgba(0,0,0,.58)\",\n  vignetteColor = \"rgba(0,30,51,.58)\",\n  scanlineColor = \"rgba(0,0,0,.32)\",\n  fontFamily = DEFAULT_FONT,\n  fontSize = 84,\n  bottom = 120,\n  maxWordsPerGroup = 4,\n  pauseThresholdMs = 150,\n  showScanlines = true,\n}: CaptionGlitchRgbProps) => {\n  const frame = useCurrentFrame();\n  const {fps} = useVideoConfig();\n  const nowMs = (frame / fps) * 1000;\n  const groups = groupCaptionWords(words, maxWordsPerGroup, pauseThresholdMs);\n  const group = groups.find(\n    (candidate) => nowMs >= candidate.startMs && nowMs < candidate.endMs,\n  );\n\n  if (!group) return null;\n\n  const groupIn = interpolate(\n    nowMs,\n    [group.startMs, group.startMs + 110],\n    [0, 1],\n    {...clamp, easing: Easing.out(Easing.cubic)},\n  );\n  const groupOut = interpolate(\n    nowMs,\n    [group.endMs - 90, group.endMs],\n    [1, 0],\n    {...clamp, easing: Easing.in(Easing.cubic)},\n  );\n  const groupOpacity = Math.min(groupIn, groupOut);\n\n  return (\n    <AbsoluteFill style={{pointerEvents: \"none\"}}>\n      <AbsoluteFill\n        style={{\n          background: `linear-gradient(to bottom, transparent 44%, transparent 58%, ${vignetteColor} 100%)`,\n        }}\n      />\n      {showScanlines ? (\n        <AbsoluteFill\n          style={{\n            opacity: 0.12,\n            backgroundImage: `repeating-linear-gradient(to bottom, transparent 0px, transparent 3px, ${scanlineColor} 3px, ${scanlineColor} 4px)`,\n          }}\n        />\n      ) : null}\n      <div\n        style={{\n          position: \"absolute\",\n          left: 0,\n          right: 0,\n          bottom,\n          display: \"flex\",\n          flexWrap: \"wrap\",\n          justifyContent: \"center\",\n          alignItems: \"flex-end\",\n          gap: 14,\n          padding: \"0 100px\",\n          opacity: groupOpacity,\n          fontFamily,\n        }}\n      >\n        {group.words.map((word) => {\n          const wordIndex = words.indexOf(word);\n          const availableMs = Math.max(\n            80,\n            Math.min(240, word.endMs - word.startMs - 20),\n          );\n          const attackEnd = word.startMs + availableMs * 0.35;\n          const settleEnd = word.startMs + availableMs;\n          const attack = interpolate(\n            nowMs,\n            [word.startMs, attackEnd],\n            [0, 1],\n            clamp,\n          );\n          const settle = interpolate(\n            nowMs,\n            [attackEnd, settleEnd],\n            [1, 0],\n            {...clamp, easing: Easing.out(Easing.cubic)},\n          );\n          const glitch = Math.min(attack, settle);\n          const travel = deterministicTravel(wordIndex);\n          const shadow = 5 + (wordIndex % 5);\n\n          return (\n            <span\n              key={`${word.startMs}-${word.text}`}\n              style={{\n                display: \"inline-block\",\n                color: textColor,\n                fontSize,\n                fontWeight: 900,\n                letterSpacing: -0.7,\n                lineHeight: 0.98,\n                textShadow:\n                  glitch > 0.01\n                    ? `${shadow * glitch}px 0 ${fringeAColor}, ${-shadow * glitch}px 0 ${fringeBColor}, 0 5px 18px ${textShadowColor}`\n                    : `0 5px 18px ${textShadowColor}`,\n                transform: `translateX(${-travel * glitch}px) skewX(${-2.5 * glitch}deg)`,\n              }}\n            >\n              {word.text}\n            </span>\n          );\n        })}\n      </div>\n    </AbsoluteFill>\n  );\n};\n","source/components/PresenterCardMorph.tsx":"import type {CSSProperties, ReactNode} from \"react\";\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from \"remotion\";\n\nexport type PresenterCardMorphPreset = \"sideSwapBridge\" | \"pipToSplit\";\n\nexport type PresenterCardRect = {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  borderRadius: number;\n};\n\nexport type PresenterCropTransform = {\n  scale: number;\n  translateX: number;\n  translateY: number;\n  originX: number;\n  originY: number;\n};\n\nexport type PresenterCardMorphProps = {\n  video: ReactNode;\n  preset: PresenterCardMorphPreset;\n  startFrame: number;\n  durationInFrames?: number;\n  from?: Partial<PresenterCardRect>;\n  to?: Partial<PresenterCardRect>;\n  fromCrop?: Partial<PresenterCropTransform>;\n  toCrop?: Partial<PresenterCropTransform>;\n  fromScene?: ReactNode;\n  toScene?: ReactNode;\n  sceneTransition?: \"crossfade\" | \"cut\";\n  sceneBlendRange?: [number, number];\n  cardBackground?: string;\n  border?: string;\n  boxShadow?: string;\n  contentStyle?: CSSProperties;\n};\n\nconst cropDefaults: PresenterCropTransform = {\n  scale: 1,\n  translateX: 0,\n  translateY: 0,\n  originX: 50,\n  originY: 38,\n};\n\nconst presetRects = (\n  preset: PresenterCardMorphPreset,\n  width: number,\n  height: number,\n): {from: PresenterCardRect; to: PresenterCardRect} => {\n  const splitWidth = width * 0.395;\n  const splitHeight = height * 0.8;\n  const splitTop = height * 0.1;\n\n  if (preset === \"sideSwapBridge\") {\n    return {\n      from: {\n        x: width * 0.55,\n        y: splitTop,\n        width: splitWidth,\n        height: splitHeight,\n        borderRadius: width * 0.012,\n      },\n      to: {\n        x: width * 0.055,\n        y: splitTop,\n        width: splitWidth,\n        height: splitHeight,\n        borderRadius: width * 0.012,\n      },\n    };\n  }\n\n  return {\n    from: {\n      x: width * 0.038,\n      y: height * 0.765,\n      width: width * 0.18,\n      height: height * 0.18,\n      borderRadius: width * 0.009,\n    },\n    to: {\n      x: width * 0.55,\n      y: splitTop,\n      width: splitWidth,\n      height: splitHeight,\n      borderRadius: width * 0.012,\n    },\n  };\n};\n\nconst mergeRect = (\n  base: PresenterCardRect,\n  override?: Partial<PresenterCardRect>,\n): PresenterCardRect => ({...base, ...override});\n\nconst mergeCrop = (\n  override?: Partial<PresenterCropTransform>,\n): PresenterCropTransform => ({...cropDefaults, ...override});\n\nconst mix = (from: number, to: number, progress: number) =>\n  interpolate(progress, [0, 1], [from, to]);\n\nexport const PresenterCardMorph = ({\n  video,\n  preset,\n  startFrame,\n  durationInFrames,\n  from,\n  to,\n  fromCrop,\n  toCrop,\n  fromScene,\n  toScene,\n  sceneTransition = \"crossfade\",\n  sceneBlendRange = [0.34, 0.66],\n  cardBackground = \"#111111\",\n  border = \"1px solid rgba(255,255,255,0.28)\",\n  boxShadow = \"0 28px 76px rgba(0,0,0,0.28)\",\n  contentStyle,\n}: PresenterCardMorphProps) => {\n  const frame = useCurrentFrame();\n  const {fps, width, height} = useVideoConfig();\n  const defaults = presetRects(preset, width, height);\n  const fromRect = mergeRect(defaults.from, from);\n  const toRect = mergeRect(defaults.to, to);\n  const cropStart = mergeCrop(fromCrop);\n  const cropEnd = mergeCrop(toCrop);\n  const transitionFrames = Math.max(\n    1,\n    durationInFrames ?? Math.round(fps * 0.83),\n  );\n  const progress = interpolate(\n    frame,\n    [startFrame, startFrame + transitionFrames],\n    [0, 1],\n    {\n      extrapolateLeft: \"clamp\",\n      extrapolateRight: \"clamp\",\n      easing: Easing.bezier(0.16, 1, 0.3, 1),\n    },\n  );\n  const [blendStart, blendEnd] = sceneBlendRange;\n  const sceneMix =\n    sceneTransition === \"cut\"\n      ? progress >= (blendStart + blendEnd) / 2\n        ? 1\n        : 0\n      : interpolate(progress, [blendStart, blendEnd], [0, 1], {\n          extrapolateLeft: \"clamp\",\n          extrapolateRight: \"clamp\",\n        });\n\n  const cardRect: PresenterCardRect = {\n    x: mix(fromRect.x, toRect.x, progress),\n    y: mix(fromRect.y, toRect.y, progress),\n    width: mix(fromRect.width, toRect.width, progress),\n    height: mix(fromRect.height, toRect.height, progress),\n    borderRadius: mix(\n      fromRect.borderRadius,\n      toRect.borderRadius,\n      progress,\n    ),\n  };\n  const crop: PresenterCropTransform = {\n    scale: mix(cropStart.scale, cropEnd.scale, progress),\n    translateX: mix(cropStart.translateX, cropEnd.translateX, progress),\n    translateY: mix(cropStart.translateY, cropEnd.translateY, progress),\n    originX: mix(cropStart.originX, cropEnd.originX, progress),\n    originY: mix(cropStart.originY, cropEnd.originY, progress),\n  };\n\n  return (\n    <AbsoluteFill style={{overflow: \"hidden\"}}>\n      {fromScene ? (\n        <AbsoluteFill style={{opacity: toScene ? 1 - sceneMix : 1}}>\n          {fromScene}\n        </AbsoluteFill>\n      ) : null}\n      {toScene ? (\n        <AbsoluteFill style={{opacity: fromScene ? sceneMix : 1}}>\n          {toScene}\n        </AbsoluteFill>\n      ) : null}\n\n      <div\n        style={{\n          position: \"absolute\",\n          left: cardRect.x,\n          top: cardRect.y,\n          width: cardRect.width,\n          height: cardRect.height,\n          overflow: \"hidden\",\n          borderRadius: cardRect.borderRadius,\n          background: cardBackground,\n          border,\n          boxShadow,\n          willChange: \"left, top, width, height, border-radius\",\n        }}\n      >\n        <AbsoluteFill\n          style={{\n            ...contentStyle,\n            transform: `translate(${crop.translateX}px, ${crop.translateY}px) scale(${crop.scale})`,\n            transformOrigin: `${crop.originX}% ${crop.originY}%`,\n            willChange: \"transform\",\n          }}\n        >\n          {video}\n        </AbsoluteFill>\n      </div>\n    </AbsoluteFill>\n  );\n};\n","source/components/FullFramePresenterBridge.tsx":"import type {CSSProperties, ReactNode} from \"react\";\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from \"remotion\";\n\nexport type FullFrameBridgeRect = {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  borderRadius: number;\n};\n\nexport type FullFrameBridgeCrop = {\n  scale: number;\n  translateX: number;\n  translateY: number;\n  originX: number;\n  originY: number;\n};\n\nexport type FullFramePresenterBridgeProps = {\n  video: ReactNode;\n  graphic: ReactNode;\n  sceneDurationInFrames: number;\n  target: FullFrameBridgeRect;\n  enterFrames?: number;\n  exitFrames?: number;\n  fullRect?: Partial<FullFrameBridgeRect>;\n  fullCrop?: Partial<FullFrameBridgeCrop>;\n  targetCrop?: Partial<FullFrameBridgeCrop>;\n  cardBackground?: string;\n  borderColor?: string;\n  borderWidth?: number;\n  shadowColor?: string;\n  contentStyle?: CSSProperties;\n};\n\nconst cropDefaults: FullFrameBridgeCrop = {\n  scale: 1,\n  translateX: 0,\n  translateY: 0,\n  originX: 50,\n  originY: 38,\n};\n\nconst mix = (from: number, to: number, progress: number) =>\n  interpolate(progress, [0, 1], [from, to]);\n\nconst easedProgress = (frame: number, start: number, duration: number) =>\n  interpolate(frame, [start, start + Math.max(1, duration)], [0, 1], {\n    extrapolateLeft: \"clamp\",\n    extrapolateRight: \"clamp\",\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n  });\n\nexport const FullFramePresenterBridge = ({\n  video,\n  graphic,\n  sceneDurationInFrames,\n  target,\n  enterFrames = 20,\n  exitFrames = 20,\n  fullRect,\n  fullCrop,\n  targetCrop,\n  cardBackground = \"#001E33\",\n  borderColor = \"rgba(0,118,189,0.34)\",\n  borderWidth = 1,\n  shadowColor = \"rgba(0,30,51,0.22)\",\n  contentStyle,\n}: FullFramePresenterBridgeProps) => {\n  const frame = useCurrentFrame();\n  const {width, height} = useVideoConfig();\n  const full: FullFrameBridgeRect = {\n    x: 0,\n    y: 0,\n    width,\n    height,\n    borderRadius: 0,\n    ...fullRect,\n  };\n  const cropStart = {...cropDefaults, ...fullCrop};\n  const cropEnd = {...cropDefaults, ...targetCrop};\n  const exitStart = Math.max(\n    enterFrames,\n    sceneDurationInFrames - exitFrames - 1,\n  );\n  const enter = easedProgress(frame, 0, enterFrames);\n  const exit = easedProgress(frame, exitStart, exitFrames);\n  const cardProgress = frame >= exitStart ? 1 - exit : enter;\n  const rect: FullFrameBridgeRect = {\n    x: mix(full.x, target.x, cardProgress),\n    y: mix(full.y, target.y, cardProgress),\n    width: mix(full.width, target.width, cardProgress),\n    height: mix(full.height, target.height, cardProgress),\n    borderRadius: mix(full.borderRadius, target.borderRadius, cardProgress),\n  };\n  const crop: FullFrameBridgeCrop = {\n    scale: mix(cropStart.scale, cropEnd.scale, cardProgress),\n    translateX: mix(\n      cropStart.translateX,\n      cropEnd.translateX,\n      cardProgress,\n    ),\n    translateY: mix(\n      cropStart.translateY,\n      cropEnd.translateY,\n      cardProgress,\n    ),\n    originX: mix(cropStart.originX, cropEnd.originX, cardProgress),\n    originY: mix(cropStart.originY, cropEnd.originY, cardProgress),\n  };\n\n  return (\n    <AbsoluteFill style={{overflow: \"hidden\"}}>\n      <AbsoluteFill>{graphic}</AbsoluteFill>\n      <div\n        style={{\n          position: \"absolute\",\n          left: rect.x,\n          top: rect.y,\n          width: rect.width,\n          height: rect.height,\n          overflow: \"hidden\",\n          borderRadius: rect.borderRadius,\n          background: cardBackground,\n          border: `${borderWidth * cardProgress}px solid ${borderColor}`,\n          boxShadow: `0 ${28 * cardProgress}px ${80 * cardProgress}px ${shadowColor}`,\n          boxSizing: \"border-box\",\n          willChange: \"left, top, width, height, border-radius\",\n        }}\n      >\n        <AbsoluteFill\n          style={{\n            ...contentStyle,\n            transform: `translate(${crop.translateX}px, ${crop.translateY}px) scale(${crop.scale})`,\n            transformOrigin: `${crop.originX}% ${crop.originY}%`,\n            willChange: \"transform\",\n          }}\n        >\n          {video}\n        </AbsoluteFill>\n      </div>\n    </AbsoluteFill>\n  );\n};\n","source/components/EditorialSystemsDiagram.tsx":"import type {ReactNode} from \"react\";\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from \"remotion\";\n\nexport type EditorialSystemNode = {\n  id: string;\n  title: string;\n  detail?: string;\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  revealFrame: number;\n  accent?: boolean;\n};\n\nexport type EditorialSystemConnection = {\n  id: string;\n  path: string;\n  revealFrame: number;\n  drawDuration?: number;\n  dashed?: boolean;\n  arrow?: boolean;\n};\n\nexport type EditorialSystemMarker = {\n  id: string;\n  label: string;\n  x: number;\n  y: number;\n  revealFrame: number;\n};\n\nexport type EditorialSystemsDiagramProps = {\n  nodes: EditorialSystemNode[];\n  connections: EditorialSystemConnection[];\n  markers?: EditorialSystemMarker[];\n  kicker?: string;\n  presenter?: ReactNode;\n  presenterRect?: {x: number; y: number; width: number; height: number};\n  background?: string;\n  gridColor?: string;\n  accentColor?: string;\n  headingColor?: string;\n  bodyColor?: string;\n  fontFamily?: string;\n  headingFontFamily?: string;\n};\n\nconst reveal = (frame: number, start: number, duration = 16) =>\n  interpolate(frame, [start, start + duration], [0, 1], {\n    extrapolateLeft: \"clamp\",\n    extrapolateRight: \"clamp\",\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n  });\n\nexport const EditorialSystemsDiagram = ({\n  nodes,\n  connections,\n  markers = [],\n  kicker,\n  presenter,\n  presenterRect,\n  background = \"#F6F7F7\",\n  gridColor = \"rgba(110,111,113,0.13)\",\n  accentColor = \"#0076BD\",\n  headingColor = \"#004472\",\n  bodyColor = \"#6E6F71\",\n  fontFamily = '\"Arial Nova\", Arial, Helvetica, sans-serif',\n  headingFontFamily = '\"Arial Nova\", Arial, Helvetica, sans-serif',\n}: EditorialSystemsDiagramProps) => {\n  const frame = useCurrentFrame();\n  const {width, height} = useVideoConfig();\n  const pip = presenterRect ?? {\n    x: width * 0.04,\n    y: height * 0.765,\n    width: width * 0.19,\n    height: height * 0.19,\n  };\n\n  return (\n    <AbsoluteFill\n      style={{\n        overflow: \"hidden\",\n        background,\n        color: headingColor,\n        fontFamily,\n      }}\n    >\n      <AbsoluteFill\n        style={{\n          backgroundImage: [\n            `linear-gradient(${gridColor} 1px, transparent 1px)`,\n            `linear-gradient(90deg, ${gridColor} 1px, transparent 1px)`,\n            `radial-gradient(circle at 50% 45%, rgba(255,255,255,0.8), transparent 58%)`,\n          ].join(\",\"),\n          backgroundSize: \"104px 104px, 104px 104px, 100% 100%\",\n        }}\n      />\n\n      {kicker ? (\n        <div\n          style={{\n            position: \"absolute\",\n            left: width * 0.05,\n            top: height * 0.055,\n            color: bodyColor,\n            fontSize: width * 0.016,\n            fontWeight: 700,\n            letterSpacing: width * 0.003,\n            textTransform: \"uppercase\",\n          }}\n        >\n          {kicker}\n        </div>\n      ) : null}\n\n      <svg\n        width={width}\n        height={height}\n        viewBox={`0 0 ${width} ${height}`}\n        style={{position: \"absolute\", inset: 0}}\n      >\n        <defs>\n          <marker\n            id=\"editorial-system-arrow\"\n            markerWidth=\"10\"\n            markerHeight=\"10\"\n            refX=\"8\"\n            refY=\"5\"\n            orient=\"auto\"\n            markerUnits=\"strokeWidth\"\n          >\n            <path d=\"M 0 0 L 10 5 L 0 10 z\" fill={accentColor} />\n          </marker>\n        </defs>\n        {connections.map((connection) => {\n          const progress = reveal(\n            frame,\n            connection.revealFrame,\n            connection.drawDuration ?? 20,\n          );\n\n          return (\n            <path\n              key={connection.id}\n              d={connection.path}\n              fill=\"none\"\n              stroke={accentColor}\n              strokeWidth={Math.max(4, width * 0.003)}\n              strokeLinecap=\"round\"\n              strokeDasharray={connection.dashed ? \"10 12\" : 1}\n              pathLength={connection.dashed ? undefined : 1}\n              strokeDashoffset={connection.dashed ? 0 : 1 - progress}\n              opacity={progress}\n              markerEnd={\n                connection.arrow !== false && progress > 0.97\n                  ? \"url(#editorial-system-arrow)\"\n                  : undefined\n              }\n            />\n          );\n        })}\n      </svg>\n\n      {nodes.map((node) => {\n        const progress = reveal(frame, node.revealFrame);\n\n        return (\n          <div\n            key={node.id}\n            style={{\n              position: \"absolute\",\n              left: node.x,\n              top: node.y,\n              width: node.width,\n              height: node.height,\n              boxSizing: \"border-box\",\n              display: \"flex\",\n              flexDirection: \"column\",\n              alignItems: \"center\",\n              justifyContent: \"center\",\n              padding: \"20px 28px\",\n              borderRadius: 22,\n              border: `2px solid ${\n                node.accent ? accentColor : \"rgba(110,111,113,0.22)\"\n              }`,\n              background: node.accent ? accentColor : \"rgba(255,255,255,0.96)\",\n              boxShadow: \"0 20px 54px rgba(0,68,114,0.13)\",\n              opacity: progress,\n              transform: `translateY(${(1 - progress) * 22}px) scale(${0.97 + progress * 0.03})`,\n              textAlign: \"center\",\n            }}\n          >\n            <div\n              style={{\n                color: node.accent ? \"#FFFFFF\" : headingColor,\n                fontFamily: headingFontFamily,\n                fontSize: Math.min(node.height * 0.34, node.width * 0.12),\n                fontWeight: 700,\n                lineHeight: 1.02,\n              }}\n            >\n              {node.title}\n            </div>\n            {node.detail ? (\n              <div\n                style={{\n                  marginTop: 12,\n                  color: node.accent ? \"rgba(255,255,255,0.82)\" : bodyColor,\n                  fontSize: Math.min(node.height * 0.19, node.width * 0.064),\n                  lineHeight: 1.18,\n                }}\n              >\n                {node.detail}\n              </div>\n            ) : null}\n          </div>\n        );\n      })}\n\n      {markers.map((marker) => {\n        const progress = reveal(frame, marker.revealFrame, 12);\n\n        return (\n          <div\n            key={marker.id}\n            style={{\n              position: \"absolute\",\n              left: marker.x,\n              top: marker.y,\n              width: 54,\n              height: 54,\n              display: \"grid\",\n              placeItems: \"center\",\n              borderRadius: \"50%\",\n              background: accentColor,\n              color: \"#FFFFFF\",\n              border: \"4px solid rgba(255,255,255,0.9)\",\n              boxShadow: \"0 10px 26px rgba(0,68,114,0.18)\",\n              fontSize: 23,\n              fontWeight: 700,\n              opacity: progress,\n              transform: `scale(${0.72 + progress * 0.28})`,\n            }}\n          >\n            {marker.label}\n          </div>\n        );\n      })}\n\n      {presenter ? (\n        <div\n          style={{\n            position: \"absolute\",\n            left: pip.x,\n            top: pip.y,\n            width: pip.width,\n            height: pip.height,\n            overflow: \"hidden\",\n            borderRadius: 18,\n            background: \"#111111\",\n            border: \"1px solid rgba(255,255,255,0.7)\",\n            boxShadow: \"0 24px 60px rgba(0,0,0,0.24)\",\n          }}\n        >\n          {presenter}\n        </div>\n      ) : null}\n    </AbsoluteFill>\n  );\n};\n","source/components/DualShowcase.tsx":"import type {CSSProperties, ReactNode} from 'react';\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from 'remotion';\n\nexport type ShowcaseRect = {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  borderRadius: number;\n};\n\nexport type DualShowcaseItem = {\n  content: ReactNode;\n  revealFrame: number;\n  label?: string;\n  rect?: Partial<ShowcaseRect>;\n  background?: string;\n  contentStyle?: CSSProperties;\n};\n\nexport type DualShowcaseProps = {\n  presenter: ReactNode;\n  left: DualShowcaseItem;\n  right: DualShowcaseItem;\n  caption?: ReactNode;\n  captionRevealFrame?: number;\n  backdropDim?: number;\n  cardBorder?: string;\n  cardShadow?: string;\n  fontFamily?: string;\n  entranceFrames?: number;\n  exitFrames?: number;\n};\n\nconst reveal = (frame: number, start: number, duration: number) =>\n  interpolate(frame, [start, start + duration], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n  });\n\nconst mergeRect = (\n  base: ShowcaseRect,\n  override?: Partial<ShowcaseRect>,\n): ShowcaseRect => ({...base, ...override});\n\nexport const DualShowcase = ({\n  presenter,\n  left,\n  right,\n  caption,\n  captionRevealFrame,\n  backdropDim = 0.18,\n  cardBorder = '2px solid rgba(255,255,255,0.72)',\n  cardShadow = '0 34px 90px rgba(0,0,0,0.38)',\n  fontFamily = '\"Arial Nova\", Arial, Helvetica, sans-serif',\n  entranceFrames = 22,\n  exitFrames = 16,\n}: DualShowcaseProps) => {\n  const frame = useCurrentFrame();\n  const {width, height, durationInFrames} = useVideoConfig();\n  const cardWidth = width * 0.275;\n  const cardHeight = height * 0.82;\n  const cardY = height * 0.09;\n  const sideInset = width * 0.055;\n  const radius = width * 0.024;\n  const leftRect = mergeRect(\n    {\n      x: sideInset,\n      y: cardY,\n      width: cardWidth,\n      height: cardHeight,\n      borderRadius: radius,\n    },\n    left.rect,\n  );\n  const rightRect = mergeRect(\n    {\n      x: width - sideInset - cardWidth,\n      y: cardY,\n      width: cardWidth,\n      height: cardHeight,\n      borderRadius: radius,\n    },\n    right.rect,\n  );\n  const exit =\n    exitFrames > 0\n      ? interpolate(\n          frame,\n          [durationInFrames - exitFrames, durationInFrames],\n          [1, 0],\n          {\n            extrapolateLeft: 'clamp',\n            extrapolateRight: 'clamp',\n            easing: Easing.in(Easing.cubic),\n          },\n        )\n      : 1;\n\n  const renderCard = (\n    item: DualShowcaseItem,\n    rect: ShowcaseRect,\n    side: 'left' | 'right',\n  ) => {\n    const progress = reveal(frame, item.revealFrame, entranceFrames);\n    const offset = (1 - progress) * (side === 'left' ? -74 : 74);\n\n    return (\n      <div\n        style={{\n          position: 'absolute',\n          left: rect.x,\n          top: rect.y,\n          width: rect.width,\n          height: rect.height,\n          overflow: 'hidden',\n          borderRadius: rect.borderRadius,\n          background: item.background ?? '#FFFFFF',\n          border: cardBorder,\n          boxShadow: cardShadow,\n          opacity: progress,\n          transform: `translateX(${offset}px) scale(${0.965 + progress * 0.035})`,\n          willChange: 'transform, opacity',\n        }}\n      >\n        <AbsoluteFill style={item.contentStyle}>{item.content}</AbsoluteFill>\n        {item.label ? (\n          <div\n            style={{\n              position: 'absolute',\n              left: 22,\n              top: 22,\n              padding: '10px 15px',\n              borderRadius: 12,\n              background: 'rgba(0,68,114,0.9)',\n              color: '#FFFFFF',\n              fontSize: Math.max(18, width * 0.011),\n              fontWeight: 700,\n              letterSpacing: 0.2,\n            }}\n          >\n            {item.label}\n          </div>\n        ) : null}\n      </div>\n    );\n  };\n\n  const captionProgress = caption\n    ? reveal(\n        frame,\n        captionRevealFrame ?? Math.min(left.revealFrame, right.revealFrame),\n        16,\n      )\n    : 0;\n\n  return (\n    <AbsoluteFill\n      style={{overflow: 'hidden', fontFamily, opacity: exit, color: '#FFFFFF'}}\n    >\n      <AbsoluteFill>{presenter}</AbsoluteFill>\n      <AbsoluteFill\n        style={{\n          background: [\n            `rgba(0,0,0,${backdropDim})`,\n            'linear-gradient(90deg, rgba(0,20,36,0.24), transparent 34%, transparent 66%, rgba(0,20,36,0.24))',\n            'linear-gradient(0deg, rgba(0,0,0,0.25), transparent 34%)',\n          ].join(','),\n          pointerEvents: 'none',\n        }}\n      />\n      {renderCard(left, leftRect, 'left')}\n      {renderCard(right, rightRect, 'right')}\n      {caption ? (\n        <div\n          style={{\n            position: 'absolute',\n            left: width * 0.33,\n            right: width * 0.33,\n            bottom: height * 0.035,\n            display: 'flex',\n            justifyContent: 'center',\n            opacity: captionProgress,\n            transform: `translateY(${(1 - captionProgress) * 18}px)`,\n            textAlign: 'center',\n          }}\n        >\n          {caption}\n        </div>\n      ) : null}\n    </AbsoluteFill>\n  );\n};\n","source/components/PrimaryMediaShowcase.tsx":"import type {CSSProperties, ReactNode} from 'react';\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from 'remotion';\n\nexport type PrimaryMediaRect = {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  borderRadius: number;\n};\n\nexport type PresenterPipPosition =\n  | 'bottom-right'\n  | 'bottom-left'\n  | 'top-right'\n  | 'top-left';\n\nexport type PrimaryMediaShowcaseProps = {\n  media: ReactNode;\n  presenter?: ReactNode;\n  mediaRevealFrame: number;\n  presenterRevealFrame?: number;\n  mediaRect?: Partial<PrimaryMediaRect>;\n  presenterRect?: Partial<PrimaryMediaRect>;\n  presenterPosition?: PresenterPipPosition;\n  presenterShape?: 'circle' | 'rounded';\n  background?: string;\n  mediaBackground?: string;\n  mediaBorder?: string;\n  mediaShadow?: string;\n  mediaContentStyle?: CSSProperties;\n  presenterContentStyle?: CSSProperties;\n  entranceFrames?: number;\n  exitFrames?: number;\n};\n\nconst reveal = (frame: number, start: number, duration: number) =>\n  interpolate(frame, [start, start + duration], [0, 1], {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing: Easing.bezier(0.16, 1, 0.3, 1),\n  });\n\nconst mergeRect = (\n  base: PrimaryMediaRect,\n  override?: Partial<PrimaryMediaRect>,\n): PrimaryMediaRect => ({...base, ...override});\n\nexport const PrimaryMediaShowcase = ({\n  media,\n  presenter,\n  mediaRevealFrame,\n  presenterRevealFrame,\n  mediaRect,\n  presenterRect,\n  presenterPosition = 'bottom-right',\n  presenterShape = 'circle',\n  background = '#E6E7E8',\n  mediaBackground = '#FFFFFF',\n  mediaBorder = '1px solid rgba(0,68,114,0.16)',\n  mediaShadow = '0 34px 88px rgba(0,68,114,0.16)',\n  mediaContentStyle,\n  presenterContentStyle,\n  entranceFrames = 24,\n  exitFrames = 16,\n}: PrimaryMediaShowcaseProps) => {\n  const frame = useCurrentFrame();\n  const {width, height, durationInFrames} = useVideoConfig();\n  const hasPresenter = Boolean(presenter);\n  const frameInsetX = hasPresenter ? width * 0.085 : width * 0.05;\n  const frameInsetY = hasPresenter ? height * 0.08 : height * 0.055;\n  const resolvedMediaRect = mergeRect(\n    {\n      x: frameInsetX,\n      y: frameInsetY,\n      width: width - frameInsetX * 2,\n      height: height - frameInsetY * 2,\n      borderRadius: width * 0.012,\n    },\n    mediaRect,\n  );\n  const pipSize = Math.min(width, height) * 0.31;\n  const pipInsetX = width * 0.045;\n  const pipInsetY = height * 0.035;\n  const pipX = presenterPosition.endsWith('right')\n    ? width - pipInsetX - pipSize\n    : pipInsetX;\n  const pipY = presenterPosition.startsWith('bottom')\n    ? height - pipInsetY - pipSize\n    : pipInsetY;\n  const resolvedPresenterRect = mergeRect(\n    {\n      x: pipX,\n      y: pipY,\n      width: pipSize,\n      height: pipSize,\n      borderRadius: presenterShape === 'circle' ? pipSize / 2 : width * 0.024,\n    },\n    presenterRect,\n  );\n  const mediaProgress = reveal(frame, mediaRevealFrame, entranceFrames);\n  const pipProgress = presenter\n    ? reveal(\n        frame,\n        presenterRevealFrame ?? mediaRevealFrame + Math.round(entranceFrames * 0.45),\n        18,\n      )\n    : 0;\n  const exit =\n    exitFrames > 0\n      ? interpolate(\n          frame,\n          [durationInFrames - exitFrames, durationInFrames],\n          [1, 0],\n          {\n            extrapolateLeft: 'clamp',\n            extrapolateRight: 'clamp',\n            easing: Easing.in(Easing.cubic),\n          },\n        )\n      : 1;\n\n  return (\n    <AbsoluteFill style={{overflow: 'hidden', background, opacity: exit}}>\n      <div\n        style={{\n          position: 'absolute',\n          left: resolvedMediaRect.x,\n          top: resolvedMediaRect.y,\n          width: resolvedMediaRect.width,\n          height: resolvedMediaRect.height,\n          overflow: 'hidden',\n          borderRadius: resolvedMediaRect.borderRadius,\n          background: mediaBackground,\n          border: mediaBorder,\n          boxShadow: mediaShadow,\n          opacity: mediaProgress,\n          transform: `translateY(${(1 - mediaProgress) * 28}px) scale(${0.975 + mediaProgress * 0.025})`,\n          willChange: 'transform, opacity',\n        }}\n      >\n        <AbsoluteFill style={mediaContentStyle}>{media}</AbsoluteFill>\n      </div>\n\n      {presenter ? (\n        <div\n          style={{\n            position: 'absolute',\n            left: resolvedPresenterRect.x,\n            top: resolvedPresenterRect.y,\n            width: resolvedPresenterRect.width,\n            height: resolvedPresenterRect.height,\n            overflow: 'hidden',\n            borderRadius: resolvedPresenterRect.borderRadius,\n            background: '#111111',\n            border: '3px solid rgba(255,255,255,0.92)',\n            boxShadow: '0 28px 72px rgba(0,0,0,0.3)',\n            opacity: pipProgress,\n            transform: `translateY(${(1 - pipProgress) * 24}px) scale(${0.9 + pipProgress * 0.1})`,\n            willChange: 'transform, opacity',\n          }}\n        >\n          <AbsoluteFill style={presenterContentStyle}>{presenter}</AbsoluteFill>\n        </div>\n      ) : null}\n    </AbsoluteFill>\n  );\n};\n","source/components/MinimalGradientBackground.tsx":"import type {ReactNode} from 'react';\nimport {\n  AbsoluteFill,\n  Easing,\n  interpolate,\n  useCurrentFrame,\n  useVideoConfig,\n} from 'remotion';\n\nexport type MinimalGradientScheme = 'light' | 'dark';\nexport type MinimalGradientBarMode = 'fullBleed' | 'card' | 'demo';\n\nexport type MinimalGradientBlob = {\n  color: string;\n  darkColor: string;\n  centerX: number;\n  centerY: number;\n  radius: number;\n  opacity: number;\n  driftX: number;\n  driftY: number;\n};\n\nexport type MinimalGradientBackgroundProps = {\n  scheme?: MinimalGradientScheme;\n  barMode?: MinimalGradientBarMode;\n  animationIn?: boolean;\n  animationOut?: boolean;\n  drift?: boolean;\n  stageColor?: string;\n  baseColor?: string;\n  stageDarkColor?: string;\n  baseDarkColor?: string;\n  blobs?: [MinimalGradientBlob, MinimalGradientBlob];\n  children?: ReactNode;\n};\n\nexport const minimalGradientPalettes: Record<\n  'simplicity' | 'reference',\n  [MinimalGradientBlob, MinimalGradientBlob]\n> = {\n  simplicity: [\n    {\n      color: '#66A4D9',\n      darkColor: '#0076BD',\n      centerX: 0.28,\n      centerY: 0.32,\n      radius: 950,\n      opacity: 0.68,\n      driftX: 70,\n      driftY: 42,\n    },\n    {\n      color: '#0076BD',\n      darkColor: '#004472',\n      centerX: 0.74,\n      centerY: 0.66,\n      radius: 1100,\n      opacity: 0.54,\n      driftX: -84,\n      driftY: -36,\n    },\n  ],\n  reference: [\n    {\n      color: '#ff7ac8',\n      darkColor: '#7d5cff',\n      centerX: 0.28,\n      centerY: 0.32,\n      radius: 950,\n      opacity: 0.85,\n      driftX: 70,\n      driftY: 42,\n    },\n    {\n      color: '#45d6c8',\n      darkColor: '#2d1b69',\n      centerX: 0.74,\n      centerY: 0.66,\n      radius: 1100,\n      opacity: 0.8,\n      driftX: -84,\n      driftY: -36,\n    },\n  ],\n};\n\nconst clampInterpolate = (\n  value: number,\n  input: [number, number],\n  output: [number, number],\n  easing = Easing.linear,\n) =>\n  interpolate(value, input, output, {\n    extrapolateLeft: 'clamp',\n    extrapolateRight: 'clamp',\n    easing,\n  });\n\nconst yoyoProgress = (\n  seconds: number,\n  startSeconds: number,\n  legSeconds: number,\n  legs: number,\n) => {\n  if (seconds <= startSeconds || seconds >= startSeconds + legSeconds * legs) {\n    return 0;\n  }\n\n  const elapsed = seconds - startSeconds;\n  const leg = Math.min(legs - 1, Math.floor(elapsed / legSeconds));\n  const local = (elapsed - leg * legSeconds) / legSeconds;\n  const eased = Easing.inOut(Easing.sin)(local);\n  return leg % 2 === 0 ? eased : 1 - eased;\n};\n\nexport const MinimalGradientBackground = ({\n  scheme = 'light',\n  barMode = 'demo',\n  animationIn = true,\n  animationOut = true,\n  drift = true,\n  stageColor = '#f5f5f7',\n  baseColor = '#ffffff',\n  stageDarkColor = '#000000',\n  baseDarkColor = '#0a0a0c',\n  blobs = minimalGradientPalettes.simplicity,\n  children,\n}: MinimalGradientBackgroundProps) => {\n  const frame = useCurrentFrame();\n  const {fps, width, height, durationInFrames} = useVideoConfig();\n  const seconds = frame / fps;\n  const durationSeconds = durationInFrames / fps;\n  const isDark = scheme === 'dark';\n\n  const entranceOpacity = animationIn\n    ? clampInterpolate(\n        seconds,\n        [0, 0.7],\n        [0, 1],\n        Easing.out(Easing.quad),\n      )\n    : 1;\n  const exitOpacity = animationOut\n    ? clampInterpolate(\n        seconds,\n        [Math.max(0, durationSeconds - 0.45), Math.max(0, durationSeconds - 0.05)],\n        [1, 0],\n        Easing.in(Easing.quad),\n      )\n    : 1;\n  const rootOpacity = Math.min(entranceOpacity, exitOpacity);\n  const entranceScale = animationIn\n    ? clampInterpolate(\n        seconds,\n        [0, 1.2],\n        [1.14, 1],\n        Easing.out(Easing.cubic),\n      )\n    : 1;\n  const ambient = drift ? yoyoProgress(seconds, 0.3, 2.35, 4) : 0;\n\n  const settleIntoCard = clampInterpolate(\n    seconds,\n    [3.8, 4.9],\n    [0, 1],\n    Easing.inOut(Easing.cubic),\n  );\n  const returnToFullBleed = clampInterpolate(\n    seconds,\n    [7.6, 8.6],\n    [0, 1],\n    Easing.inOut(Easing.cubic),\n  );\n  const cardAmount =\n    barMode === 'card'\n      ? 1\n      : barMode === 'fullBleed'\n        ? 0\n        : Math.min(settleIntoCard, 1 - returnToFullBleed);\n  const cardX = width * 0.125 * cardAmount;\n  const cardY = height * (140 / 1080) * cardAmount;\n  const cardWidth = width * (1 - 0.25 * cardAmount);\n  const cardHeight = height * (1 - (280 / 1080) * cardAmount);\n  const cardRadius = width * (40 / 1920) * cardAmount;\n\n  return (\n    <AbsoluteFill\n      style={{\n        overflow: 'hidden',\n        background: isDark ? stageDarkColor : stageColor,\n        opacity: rootOpacity,\n      }}\n    >\n      <div\n        style={{\n          position: 'absolute',\n          left: cardX,\n          top: cardY,\n          width: cardWidth,\n          height: cardHeight,\n          overflow: 'hidden',\n          borderRadius: cardRadius,\n          background: isDark ? baseDarkColor : baseColor,\n          boxShadow:\n            cardAmount > 0\n              ? `0 ${30 * cardAmount}px ${80 * cardAmount}px rgba(0,0,0,${0.18 * cardAmount})`\n              : 'none',\n          willChange: 'left, top, width, height, border-radius',\n        }}\n      >\n        {blobs.map((blob, index) => {\n          const diameter = blob.radius * 2;\n          const color = isDark ? blob.darkColor : blob.color;\n          const transparent = isDark ? 'rgba(0,0,0,0)' : 'rgba(255,255,255,0)';\n\n          return (\n            <div\n              key={`${color}-${index}`}\n              style={{\n                position: 'absolute',\n                left: blob.centerX * width - blob.radius,\n                top: blob.centerY * height - blob.radius,\n                width: diameter,\n                height: diameter,\n                borderRadius: '50%',\n                opacity: blob.opacity,\n                background: `radial-gradient(circle closest-side, ${color} 0%, ${transparent} 72%)`,\n                transform: `translate(${blob.driftX * ambient}px, ${blob.driftY * ambient}px) scale(${entranceScale})`,\n                willChange: 'transform',\n              }}\n            />\n          );\n        })}\n        {children}\n      </div>\n    </AbsoluteFill>\n  );\n};\n","source/components/CameraPunch.tsx":"import type { ReactNode } from \"react\";\nimport { AbsoluteFill, Easing, interpolate, useCurrentFrame } from \"remotion\";\n\nexport type CameraPunchCue = {\n  startFrame: number;\n  endFrame: number;\n  scale?: number;\n  transitionFrames?: number;\n  focusX?: number;\n  focusY?: number;\n  offsetX?: number;\n  offsetY?: number;\n};\n\nexport type CameraPunchProps = {\n  children: ReactNode;\n  cues: CameraPunchCue[];\n};\n\nconst cueProgress = (frame: number, cue: CameraPunchCue) => {\n  if (frame < cue.startFrame || frame > cue.endFrame) {\n    return 0;\n  }\n\n  const cueDuration = Math.max(2, cue.endFrame - cue.startFrame);\n  const transitionFrames = Math.min(\n    cue.transitionFrames ?? 12,\n    Math.floor(cueDuration / 2),\n  );\n  const enter = interpolate(\n    frame,\n    [cue.startFrame, cue.startFrame + transitionFrames],\n    [0, 1],\n    {\n      extrapolateLeft: \"clamp\",\n      extrapolateRight: \"clamp\",\n      easing: Easing.bezier(0.16, 1, 0.3, 1),\n    },\n  );\n  const exit = interpolate(\n    frame,\n    [cue.endFrame - transitionFrames, cue.endFrame],\n    [1, 0],\n    {\n      extrapolateLeft: \"clamp\",\n      extrapolateRight: \"clamp\",\n      easing: Easing.bezier(0.7, 0, 0.84, 0),\n    },\n  );\n\n  return Math.min(enter, exit);\n};\n\nexport const CameraPunch = ({ children, cues }: CameraPunchProps) => {\n  const frame = useCurrentFrame();\n  const activeCue = cues.find(\n    (cue) => frame >= cue.startFrame && frame <= cue.endFrame,\n  );\n  const progress = activeCue ? cueProgress(frame, activeCue) : 0;\n  const targetScale = activeCue?.scale ?? 1.08;\n  const scale = 1 + (targetScale - 1) * progress;\n  const offsetX = (activeCue?.offsetX ?? 0) * progress;\n  const offsetY = (activeCue?.offsetY ?? 0) * progress;\n  const focusX = activeCue?.focusX ?? 50;\n  const focusY = activeCue?.focusY ?? 38;\n\n  return (\n    <AbsoluteFill style={{ overflow: \"hidden\" }}>\n      <AbsoluteFill\n        style={{\n          transform: `translate(${offsetX}px, ${offsetY}px) scale(${scale})`,\n          transformOrigin: `${focusX}% ${focusY}%`,\n          willChange: \"transform\",\n        }}\n      >\n        {children}\n      </AbsoluteFill>\n    </AbsoluteFill>\n  );\n};\n","source/components/OneToThreeBranch.tsx":"import type {CSSProperties, ReactNode} from 'react';\nimport {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';\n\nexport type BranchDestination = {\n  id: string;\n  label: string;\n  /** First visible frame, relative to this component's Sequence. */\n  revealFrame: number;\n  detail?: string;\n  /** Receives the current ink color, including when this card is highlighted. */\n  icon?: (color: string) => ReactNode;\n  highlight?: boolean;\n};\nexport type BranchRect = {x: number; y: number; width: number; height: number};\nexport type OneToThreeBranchProps = {\n  title: string;\n  sourceLabel: string;\n  sourceMedia?: ReactNode;\n  sourceRevealFrame?: number;\n  branches: [BranchDestination, BranchDestination, BranchDestination];\n  presenter?: ReactNode;\n  presenterRect?: BranchRect;\n  presenterStyle?: CSSProperties;\n  sourceRect?: BranchRect;\n  destinationRect?: BranchRect;\n  destinationGap?: number;\n  revealFrames?: number;\n  drawFrames?: number;\n  highlightMode?: 'marked' | 'latest' | 'none';\n  background?: string;\n  cardColor?: string;\n  inkColor?: string;\n  accentColor?: string;\n  highlightColor?: string;\n  highlightTextColor?: string;\n  borderColor?: string;\n  fontFamily?: string;\n};\n\n/**\n * One idea branches into three, with optional uninterrupted presenter PiP.\n * Generalized from the Roth Conversion project's G04 / MoneyBuckets scene.\n * All geometry is on a 1920×1080 design canvas, fitted without distortion.\n * Timing is component-local: subtract the enclosing Sequence start exactly once.\n * This is a creative starting point; adapt it to the content and face-safe space.\n */\nexport const OneToThreeBranch = ({\n  title, sourceLabel, sourceMedia, branches, presenter,\n  sourceRevealFrame = 8,\n  presenterRect = {x:1370, y:733, width:450, height:253},\n  presenterStyle,\n  sourceRect = {x:110, y:320, width:390, height:380},\n  destinationRect = {x:850, y:225, width:465, height:160},\n  destinationGap = 50,\n  revealFrames = 14,\n  drawFrames = 16,\n  highlightMode = 'marked',\n  background = '#FFFFFF', cardColor = '#FFFFFF', inkColor = '#004472',\n  accentColor = '#0076BD', highlightColor = '#004472',\n  highlightTextColor = '#FFFFFF', borderColor = '#E6E7E8',\n  fontFamily = '\"Arial Nova\", Arial, Helvetica, sans-serif',\n}: OneToThreeBranchProps) => {\n  const frame = useCurrentFrame();\n  const {width, height} = useVideoConfig();\n  const scale = Math.min(width / 1920, height / 1080);\n  // Mount gated groups only at their cue: no dots, arrowheads or empty cards early.\n  const progress = (start: number, duration: number) => frame < start ? 0 : interpolate(\n    frame, [start - 1, start + Math.max(1, duration)], [0, 1],\n    {extrapolateLeft:'clamp', extrapolateRight:'clamp', easing:Easing.out(Easing.cubic)},\n  );\n  const reveal = (start:number):CSSProperties => ({\n    opacity:progress(start,revealFrames),\n    transform:`translateY(${(1-progress(start,revealFrames))*18}px)`,\n  });\n  const latest = branches.reduce((best, branch, index) =>\n    frame >= branch.revealFrame && (best < 0 || branch.revealFrame >= branches[best].revealFrame) ? index : best, -1);\n  const originX = sourceRect.x + sourceRect.width + 25;\n  const originY = sourceRect.y + sourceRect.height / 2;\n  return <AbsoluteFill style={{background, overflow:'hidden'}}>\n    <div style={{position:'absolute',width:1920,height:1080,left:(width-1920*scale)/2,top:(height-1080*scale)/2,transform:`scale(${scale})`,transformOrigin:'top left',fontFamily,color:inkColor}}>\n      <AbsoluteFill style={{background:`radial-gradient(ellipse at 68% 10%, ${accentColor}12, transparent 65%)`}}/>\n      <AbsoluteFill style={{opacity:.16,backgroundImage:`radial-gradient(${accentColor} 1px, transparent 1px)`,backgroundSize:'32px 32px'}}/>\n      <div style={{position:'absolute',left:100,top:85,right:100,fontSize:48,fontWeight:700,letterSpacing:-1.3,lineHeight:1.15}}>{title}</div>\n      {frame >= sourceRevealFrame && <div data-branch-source style={{position:'absolute',left:sourceRect.x,top:sourceRect.y,width:sourceRect.width,height:sourceRect.height,background:cardColor,border:`2px solid ${borderColor}`,boxShadow:'0 18px 44px rgba(0,68,114,.07)',borderRadius:22,boxSizing:'border-box',...reveal(sourceRevealFrame)}}>\n        {sourceMedia && <div style={{position:'absolute',inset:'18px 20px 92px',display:'flex',alignItems:'center',justifyContent:'center'}}>{sourceMedia}</div>}\n        <div style={{position:'absolute',left:22,right:22,...(sourceMedia?{bottom:30}:{top:'50%',transform:'translateY(-50%)'}),textAlign:'center',fontSize:34,fontWeight:700,lineHeight:1.15}}>{sourceLabel}</div>\n      </div>}\n      <svg width={1920} height={1080} viewBox='0 0 1920 1080' style={{position:'absolute',inset:0}} aria-hidden='true'>\n        {branches.map((branch,index)=>{\n          if(frame < branch.revealFrame)return null;\n          const endX=destinationRect.x-45;\n          const endY=destinationRect.y+index*(destinationRect.height+destinationGap)+destinationRect.height/2;\n          return <g key={branch.id} data-branch-connector={branch.id}>\n            <path d={`M ${originX} ${originY} C ${originX+135} ${originY} ${endX-105} ${endY} ${endX} ${endY}`} pathLength={1} fill='none' stroke={accentColor} strokeWidth={5} strokeDasharray={1} strokeDashoffset={1-progress(branch.revealFrame,drawFrames)} strokeLinecap='round'/>\n            {frame >= branch.revealFrame+drawFrames/2 && <path d={`M ${endX-18} ${endY-10} L ${endX} ${endY} L ${endX-18} ${endY+10}`} fill='none' stroke={accentColor} strokeWidth={4} opacity={progress(branch.revealFrame+drawFrames/2,drawFrames/2)}/>}\n          </g>;\n        })}\n      </svg>\n      {branches.map((branch,index)=>{\n        if(frame < branch.revealFrame)return null;\n        const active=highlightMode==='latest'?index===latest:highlightMode==='marked'&&branch.highlight;\n        const ink=active?highlightTextColor:inkColor;\n        return <div key={branch.id} data-branch-card={branch.id} style={{position:'absolute',left:destinationRect.x,top:destinationRect.y+index*(destinationRect.height+destinationGap),width:destinationRect.width,height:destinationRect.height,boxSizing:'border-box',display:'flex',alignItems:'center',gap:27,padding:'20px 30px',background:active?highlightColor:cardColor,color:ink,border:`2px solid ${active?highlightColor:borderColor}`,borderRadius:18,...reveal(branch.revealFrame)}}>\n          {branch.icon && <div style={{flex:'0 0 110px',display:'flex',justifyContent:'center'}}>{branch.icon(active?highlightTextColor:accentColor)}</div>}\n          <div style={{minWidth:0}}><div style={{fontSize:36,fontWeight:700,lineHeight:1.1}}>{branch.label}</div>{branch.detail && <div style={{fontSize:23,lineHeight:1.2,marginTop:12}}>{branch.detail}</div>}</div>\n        </div>;\n      })}\n      {presenter && <div style={{position:'absolute',left:presenterRect.x,top:presenterRect.y,width:presenterRect.width,height:presenterRect.height,overflow:'hidden',borderRadius:18,border:`1px solid ${borderColor}`,boxShadow:'0 18px 44px rgba(0,68,114,.12)',...presenterStyle}}>{presenter}</div>}\n    </div>\n  </AbsoluteFill>;\n};\n","source/components/SimulatedBCamera.tsx":"import React from 'react';\nimport {AbsoluteFill, Sequence} from 'remotion';\nimport {Video} from '@remotion/media';\n\nexport type BCameraCut = {\n  id: string;\n  from: number;\n  durationInFrames: number;\n  src: string;\n  /** Generated-media offset in composition frames. */\n  trimBefore?: number;\n};\n\n/** Keep the original presenter/audio mounted; layer muted, synchronized angles.\n * All cut frames are local to this wrapper on the edited timeline.\n */\nexport const SimulatedBCamera = ({presenter, cuts}: {\n  presenter: React.ReactNode;\n  cuts: BCameraCut[];\n}) => {\n  const ordered = [...cuts].sort((a, b) => a.from - b.from);\n  ordered.forEach((cut, i) => {\n    if (![cut.from, cut.durationInFrames, cut.trimBefore ?? 0].every(Number.isInteger) ||\n      cut.from < 0 || cut.durationInFrames < 1 || (cut.trimBefore ?? 0) < 0 ||\n      (i > 0 && ordered[i - 1].from + ordered[i - 1].durationInFrames > cut.from)) {\n      throw new Error('B-camera cuts require non-overlapping integer frame ranges.');\n    }\n  });\n  return <AbsoluteFill>\n    {presenter}\n    {ordered.map(cut => <Sequence key={cut.id} name={`B camera: ${cut.id}`}\n      from={cut.from} durationInFrames={cut.durationInFrames}>\n      <AbsoluteFill style={{background: '#000'}}>\n        <Video src={cut.src} trimBefore={cut.trimBefore ?? 0} muted\n          objectFit=\"cover\" style={{width: '100%', height: '100%'}} />\n      </AbsoluteFill>\n    </Sequence>)}\n  </AbsoluteFill>;\n};\n"};
